renderHTML:
__ht__function(data, gv, cache) {var option = {
	title: {
    show:false},
	backgroundColor: 'transparent',
	tooltip: {
		trigger: 'item',
		
	},
      //color:['#1e98e2','#fff025','#02bfba','#fb0045'],
	legend: {
		show: false
	},
	series: [{
		name: '电量',
		type: 'pie',
		selectedMode: 'single',
		radius: [0, '30%'],
		label: {
			formatter: '{b}：\n{c} {d}%',
          	position: 'inner',
			fontSize: 12,
			rich: {
				b: {
					color: '#fff',
				},
				d: {
					color: '#fff',
				},
			}
		},
		labelLine: {
			show: false
		},
		data: [],
		emphasis: {
			itemStyle: {
				shadowBlur: 10,
				shadowOffsetX: 0,
				shadowColor: 'rgba(0, 0, 0, 0.5)'
			}
		}
	}, {
		name: '电量',
		type: 'pie',
		radius: ['45%', '60%'],
		labelLine: {
			length: 2
		},
        color:['#1e98e2','#fff025','#02bfba','#fb0045'],
		label: {
			formatter: '{b}：\n{c}\n{per|{d}%}',
            //color:['#1e98e2','#fff025','#02bfba','#1e98e2'],
			rich: {
				a: {
					color: '#6E7079',
					lineHeight: 22,
					align: 'center'
				},
                b: {
					color: '#4C5058',
					fontSize: 14,
					fontWeight: 'bold',
					lineHeight: 33
				},
				per: {
				    color: '#fff',
					backgroundColor: '#4C5058',
					padding: [3, 4],
					borderRadius: 4,
                    position: 'top',
				}
			}
		},
		data: []
	}]
};

if (!cache.htmlView) {
    cache.htmlView = document.createElement('div');
    cache.htmlView.style.position = 'absolute';
    cache.htmlChart = echarts.init(cache.htmlView);

    // layoutHTML will be called when the data needs to be drawing
    cache.htmlView.layoutHTML = function () {
        gv.layoutHTML(data, cache.htmlView, false);
        cache.htmlChart.resize();
    };
}

// update data
option.series[0].data = data.a('series0.data');
option.series[1].data = data.a('series1.data');
data.a('chart.text') && (option.title.text = data.a('chart.text'));
data.a('chart.subtext') && (option.title.subtext = data.a('chart.subtext'));
data.a('chart.backgroundColor') && (option.backgroundColor = data.a('chart.backgroundColor'));

cache.htmlChart.setOption(option);

// html for showing
return cache.htmlView;}
